-- Review-gated ADITI and DRDO Technology Development Fund routes.

do $$
declare
  item jsonb;
  authority_id uuid;
  seed_opportunity_id uuid;
  version_id uuid;
begin
  for item in
    select value from jsonb_array_elements($records$[
      {"slug":"idex-aditi-critical-technologies","name":"iDEX ADITI Critical and Strategic Defence Technologies","type":"grant","status":"paused","authority":"Defence Innovation Organisation - ADITI","authority_url":"https://idex.gov.in/","canonical_url":"https://idex.gov.in/disc-category/26","source_url":"https://idex.gov.in/disc-category/26","source_kind":"agency_portal","source_title":"iDEX ADITI scheme page","source_anchor":"ADITI eligibility, critical-technology objective, grant ceiling and displayed call timeline","summary":"iDEX ADITI route for critical and strategic deep-tech technologies with defence applications; the currently displayed ADITI 1 call is historical and no current challenge is shown on the official page.","objective":"Support development and acceleration of critical and strategic defence technologies through a product-development-budget grant and milestone-based execution.","legal_basis":"iDEX framework and ADITI scheme operated by Defence Innovation Organisation under the Department of Defence Production; current challenge edition and guideline control the application.","eligibility":{"entity_types":["dpiit_recognized_startup","msme","individual_innovator","research_or_academic_institution_route"],"lifecycle_stages":["idea","validation","prototype","growth"],"industries":["defence","aerospace","deep_technology","dual_use_technology","quantum","robotics","ai"],"locations":["India"],"conditions":["technology must address a current ADITI problem statement or approved critical/strategic technology focus","startups must meet current DPIIT recognition and iDEX conditions","Indian companies primarily operating as MSMEs may apply under the current route","individual innovators may apply but must establish an eligible startup/MSME entity after selection before grant execution","product development budget, matching contribution, milestone and user-acceptance conditions apply"],"exclusions":["the displayed ADITI 1 timeline is historical and does not prove an open call","a registration or proposal does not guarantee selection or grant","iDEX does not assure minimum pilot orders or procurement","Open Challenge grant limits cannot be transferred to ADITI"],"thresholds":{"maximum_grant_inr":250000000,"grant_share":"up_to_50_percent_of_product_development_budget","applicant_matching_contribution":"at_least_50_percent_of_total_project_cost_per_current_faq","current_displayed_call":"ADITI 1 timeline ended 2024-04-19","current_call_status":"no_challenge_displayed_on_official_page"},"unknown_handling":"needs_information"},"application":{"portal":"https://idex.gov.in/","route":"Monitor the official ADITI challenge page, confirm a live edition and problem statement, create/use an iDEX account, submit technical and financial details, and comply with the current SPARK agreement if selected.","selection":"A high-powered committee and relevant nodal agencies evaluate proposals; a grant requires selection, Product Development Budget approval and agreement execution.","fees":"No universal applicant fee is asserted; confirm current portal terms.","applicant_note":"UdyamVeda can prepare technical, entity, matching-contribution and milestone evidence but cannot represent the applicant, promise selection or promise procurement."},"fine_print":{"grant":"Official iDEX material describes up to 50% of Product Development Budget with a maximum grant of INR 25 crore for ADITI, subject to the current scheme and approved budget.","call_status":"The official ADITI page currently displays ADITI 1 with a 19 April 2024 timeline and no challenge found; keep the record paused until a current edition is verified.","selection_and_procurement":"Selection, milestone release, user acceptance, certification and procurement are separate decisions; iDEX does not assure a minimum pilot order.","review_note":"Verify current ADITI edition, problem statements, deadline, Indian ownership, matching contribution, product-development budget, incubator/partner requirements, milestone agreement, testing, IP, procurement and any successor or amendment before publication."},"benefit_summary":{"types":["grant","testing_access","mentorship","market_access"],"amounts":[{"type":"grant_in_aid","max_inr":250000000}],"summary":"Potential milestone-based ADITI grant and related technical/incubation support for selected critical-technology applicants; no current open call is asserted.","separate_value_buckets":true},"benefit_type":"grant","benefit_label":"iDEX ADITI grant-in-aid for critical technologies","amount_min":null,"amount_max":250000000,"percentage":50,"benefit_conditions":{"selection_required":true,"product_development_budget_approval_required":true,"matching_contribution_required":true,"maximum_grant_inr":250000000,"current_call_must_be_verified":true},"requirement":"Current ADITI problem statement, technical/product-development proposal, eligible entity evidence and matching-contribution plan","requirement_description":"Prepare DPIIT/MSME or innovator evidence, technical response, product-development budget, milestone plan, matching-contribution evidence, IP and testing plan, and current portal documents.","rules":{"all":[{"field":"aditi_call_currently_open","operator":"equals","value":true},{"field":"critical_defence_technology_fit_verified","operator":"equals","value":true},{"field":"eligible_applicant_type_verified","operator":"equals","value":true},{"field":"matching_contribution_plan_verified","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Check for a live ADITI edition","description":"Confirm that the official portal shows a current call and problem statement; the displayed ADITI 1 page is historical.","url":"https://idex.gov.in/disc-category/26"},{"title":"Map the critical technology and entity route","description":"Confirm applicant category, Indian ownership, DPIIT/MSME evidence and the relevant ADITI focus.","url":"https://idex.gov.in/faq"},{"title":"Prepare budget and milestone evidence","description":"Build the Product Development Budget, matching-contribution plan, technical proposal and testing path.","url":"https://www.idex.gov.in/uploads/page/aditi_scheeme.pdf"},{"title":"Apply only through the live iDEX route","description":"Submit through the current portal when an edition is open and retain selection/agreement records.","url":"https://idex.gov.in/"}],"window_type":"static","window_close_at":null,"window_label":"Paused: the official ADITI page displays a historical 19 April 2024 timeline and no current challenge; verify a new edition before actioning.","window_evidence":{"source_url":"https://idex.gov.in/disc-category/26","anchor":"ADITI 1 timeline and Challenge: No Challenge Found"},"review_note":"Keep paused and review-gated. Do not present the INR 25 crore ceiling as currently available funding."},
      {"slug":"drdo-technology-development-fund-startup-msme","name":"DRDO Technology Development Fund (TDF) for Startups and MSMEs","type":"grant","status":"paused","authority":"Defence Research and Development Organisation - Technology Development Fund","authority_url":"https://tdf.drdo.gov.in/","canonical_url":"https://tdf.drdo.gov.in/","source_url":"https://tdf.drdo.gov.in/faq","source_kind":"faq","source_title":"TDF FAQ","source_anchor":"Project cost ceiling, duration, applicant entities, resident-Indian control, online application and milestone funding","summary":"DRDO grant-in-aid and technology-development route for Indian startups and MSMEs developing defence or dual-use systems and prototypes; the portal currently reports no projects available at this stage.","objective":"Support Indian-designed, developed and manufactured defence or dual-use technologies with potential use by the Services through project-specific TDF calls.","legal_basis":"DRDO Technology Development Fund scheme and current operating procedure/terms; each project definition, evaluation and live portal notice controls the application.","eligibility":{"entity_types":["proprietorship","partnership","llp","private_limited_company","startup","msme","consortium_or_association_of_persons"],"lifecycle_stages":["idea","validation","prototype","growth"],"industries":["defence","aerospace","dual_use_technology","advanced_manufacturing","electronics","robotics","materials"],"locations":["India"],"conditions":["applicant must be resident-Indian owned and controlled within the current TDF terms","foreign investment or partnership must remain within the current published limit","project must develop a defence/dual-use system, subsystem, component or technology with potential Service use","project cost and duration must fit the current TDF financial and schedule criteria","startup/MSME recognition and technical capability evidence are required","project-specific EOI/DPR, evaluation, NDA, security, testing and agreement conditions apply"],"exclusions":["non-profit applicants are not eligible under the current FAQ","research/educational institution involvement is subject to the published share and lead-agency conditions","submission or EOI does not guarantee award","test facilities may be chargeable and access is subject to custodian priority"],"thresholds":{"project_cost_ceiling_inr":100000000,"typical_duration_years":2,"general_grant_share_percent":90,"case_by_case_max_grant_share_percent":100,"foreign_investment_or_partnership_max_percent":49,"research_or_education_involvement_max_percent":40,"maximum_concurrent_projects":3,"maximum_concurrent_lead_projects":2},"unknown_handling":"needs_information"},"application":{"portal":"https://tdf.drdo.gov.in/public/innovator/register","route":"Register as an industry, monitor the live project list/DefProc route, review the project definition and terms, submit the required EOI/DPR and complete technical and financial evaluation steps.","selection":"DTDF/DRDO evaluates project fit, technical capability, DPR and terms; a grant letter/agreement and milestones control release.","fees":"No universal application fee is asserted; testing, facilities, security and project-specific charges must be confirmed.","applicant_note":"UdyamVeda can prepare entity, recognition, technical, DPR, budget and compliance evidence but cannot represent the applicant or guarantee a TDF award."},"fine_print":{"project_cost_ceiling_inr":100000000,"scope":"TDF supports Indian-designed, developed and manufactured defence and dual-use systems, subsystems, components or technologies and is intended to bring MSMEs and startups into defence technology development.","funding":"The published TDF FAQ describes up to 90% of project cost in general with case-by-case higher support; project cost, approval, matching contribution, milestone and agreement conditions control the actual award.","current_call_status":"The official TDF portal currently displays no projects available at this stage; keep the route paused until a current project or official notice is verified.","review_note":"Verify the current project list, DefProc route, 2024 SOP, eligible entity/ownership, cost ceiling, duration, grant share, consortium rules, testing, security, IP, milestones, agreement and live deadlines before publication."},"benefit_summary":{"types":["grant","testing_access","technical_support"],"amounts":[{"type":"grant_in_aid","general_max_percent":90,"case_by_case_max_percent":100}],"summary":"Potential project-specific DRDO grant-in-aid and technical/test support for selected defence or dual-use technology developers; no current open project is asserted.","separate_value_buckets":true},"benefit_type":"grant","benefit_label":"DRDO TDF project grant-in-aid","amount_min":null,"amount_max":null,"percentage":90,"benefit_conditions":{"project_selection_required":true,"defence_or_dual_use_application_required":true,"indian_design_development_manufacturing_required":true,"project_cost_and_duration_limits_apply":true,"current_project_must_be_verified":true},"requirement":"Eligible Indian entity, startup/MSME recognition, project definition, DPR, technical capability and financial/security evidence","requirement_description":"Prepare entity and ownership records, startup/MSME recognition certificate, project definition response, DPR, technical capability, cost and milestone plan, collaboration/NDA, security and testing evidence.","rules":{"all":[{"field":"tdf_project_currently_available","operator":"equals","value":true},{"field":"indian_entity_and_control_verified","operator":"equals","value":true},{"field":"defence_or_dual_use_project_fit_verified","operator":"equals","value":true},{"field":"startup_or_msme_recognition_verified","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Check the live TDF project list","description":"Confirm a current project, project-definition document, deadline and official submission route; the portal currently shows no projects available at this stage.","url":"https://tdf.drdo.gov.in/"},{"title":"Verify entity and ownership eligibility","description":"Confirm resident-Indian control, startup/MSME evidence, consortium conditions and research-institution limits.","url":"https://tdf.drdo.gov.in/faq"},{"title":"Prepare DPR and compliance evidence","description":"Prepare the technical and financial proposal, project cost, milestones, testing, security and agreement inputs.","url":"https://www.drdo.gov.in/drdo/sites/default/files/inline-files/SOP_TDF24102024.pdf"},{"title":"Register and submit through the official route","description":"Register as industry, follow the current project instructions and retain the evaluation and agreement records.","url":"https://tdf.drdo.gov.in/public/innovator/register"}],"window_type":"static","window_close_at":null,"window_label":"Paused: the official TDF portal currently displays no projects available at this stage; verify a live project notice before actioning.","window_evidence":{"source_url":"https://tdf.drdo.gov.in/","anchor":"No projects available at this stage"},"review_note":"Keep paused and review-gated. Do not present the 90% reference as a guaranteed grant or treat historical TDF project notices as open calls."}
    ]$records$::jsonb)
  loop
    authority_id := null;
    select id into authority_id from public.authorities where name = item->>'authority' and level = 'central' order by created_at, id limit 1;
    if authority_id is null then
      insert into public.authorities (name, level, ministry, department, official_url)
    values (item->>'authority', 'central', 'Ministry of Defence', 'Department of Defence Production / DRDO', item->>'authority_url')
    returning id into authority_id;
    end if;
    if authority_id is null then select id into authority_id from public.authorities where name = item->>'authority' limit 1; end if;
    seed_opportunity_id := null;
    insert into public.opportunities (slug, name, opportunity_type, status, authority_id, geography, canonical_url)
    values (item->>'slug', item->>'name', item->>'type', item->>'status', authority_id, '{"coverage":"central","locations":["India"]}'::jsonb, item->>'canonical_url')
    on conflict (slug) do update set name = excluded.name, status = excluded.status, authority_id = excluded.authority_id, canonical_url = excluded.canonical_url
    returning id into seed_opportunity_id;
    if seed_opportunity_id is null then select id into seed_opportunity_id from public.opportunities where slug = item->>'slug' limit 1; end if;
    version_id := null;
    insert into public.opportunity_versions
      (opportunity_id, version_number, title, summary, objective, legal_basis, eligibility, application, fine_print, benefit_summary, last_verified_at, completeness, confidence, review_status)
    values (seed_opportunity_id, 1, item->>'name', item->>'summary', item->>'objective', item->>'legal_basis', item->'eligibility', item->'application', item->'fine_print', item->'benefit_summary', now(), 0.9, 0.85, 'in_review')
    on conflict (opportunity_id, version_number) do nothing
    returning id into version_id;
    if version_id is null then select ov.id into version_id from public.opportunity_versions ov where ov.opportunity_id = seed_opportunity_id and ov.version_number = 1 limit 1; end if;
    update public.opportunities set current_version_id = version_id, status = item->>'status' where id = seed_opportunity_id;
    insert into public.opportunity_sources (opportunity_version_id, source_url, source_kind, source_title, source_anchor, fetched_at, is_primary)
    values
      (version_id, item->>'source_url', item->>'source_kind', item->>'source_title', item->>'source_anchor', now(), true),
      (version_id, 'https://idex.gov.in/faq', 'faq', 'iDEX FAQ', 'Category, grant, matching contribution and no-procurement-guarantee boundaries', now(), false),
      (version_id, 'https://idex.gov.in/disc-category/26', 'agency_portal', 'iDEX ADITI scheme page', 'ADITI timeline and current challenge state', now(), false),
      (version_id, 'https://www.idex.gov.in/uploads/page/aditi_scheeme.pdf', 'guideline', 'iDEX ADITI scheme guideline', 'Grant share, applicant and product-development conditions', now(), false),
      (version_id, 'https://drdo.gov.in/drdo/en/offerings/industry-support', 'agency_portal', 'DRDO industry support', 'TDF startup/MSME objective', now(), false),
      (version_id, 'https://drdo.gov.in/drdo/en/offerings/schemes-and-services/startups-support', 'agency_portal', 'DRDO TDF startup support', 'Defence and dual-use development route', now(), false),
      (version_id, 'https://tdf.drdo.gov.in/', 'agency_portal', 'TDF official portal', 'Current project availability and scheme boundary', now(), false),
      (version_id, 'https://tdf.drdo.gov.in/faq', 'faq', 'TDF FAQ', 'Entity, cost, duration and funding conditions', now(), false),
      (version_id, 'https://tdf.drdo.gov.in/public/innovator/register', 'agency_portal', 'TDF innovator registration', 'Industry registration route', now(), false),
      (version_id, 'https://www.drdo.gov.in/drdo/sites/default/files/inline-files/SOP_TDF24102024.pdf', 'guideline', 'TDF 2024 operating procedure', 'Operating procedure and evaluation route', now(), false),
      (version_id, 'https://tdf.drdo.gov.in/sites/default/files/2022-07/Terms%20and%20Conditions%20II_TDF%20Terms%20and%20Conditions%20for%20MSMEs%20and%20Startups_0.pdf', 'guideline', 'TDF terms for MSMEs and startups', 'Grant, EOI and startup/MSME terms', now(), false)
    on conflict do nothing;
    insert into public.opportunity_benefits (opportunity_version_id, benefit_type, label, amount_min, amount_max, percentage, conditions)
    select version_id, item->>'benefit_type', item->>'benefit_label', (item->>'amount_min')::numeric, (item->>'amount_max')::numeric, (item->>'percentage')::numeric, item->'benefit_conditions'
    where not exists (select 1 from public.opportunity_benefits where opportunity_version_id = version_id and label = item->>'benefit_label');
    insert into public.opportunity_requirements (opportunity_version_id, requirement_type, name, description, required)
    select version_id, 'document', item->>'requirement', item->>'requirement_description', true
    where not exists (select 1 from public.opportunity_requirements where opportunity_version_id = version_id and name = item->>'requirement');
    insert into public.eligibility_rule_sets (opportunity_version_id, rules, source_evidence, reviewed)
    select version_id, item->'rules', jsonb_build_array(jsonb_build_object('source_url', item->>'source_url', 'anchor', item->>'source_anchor')), false
    where not exists (select 1 from public.eligibility_rule_sets where opportunity_version_id = version_id);
    insert into public.opportunity_steps (opportunity_version_id, step_number, title, description, official_url)
    select version_id, row_number() over ()::integer, step->>'title', step->>'description', step->>'url'
    from jsonb_array_elements(item->'steps') as steps(step)
    where not exists (select 1 from public.opportunity_steps where opportunity_version_id = version_id);
    insert into public.opportunity_windows (opportunity_version_id, window_type, closes_at, label, source_evidence)
    select version_id, item->>'window_type', (item->>'window_close_at')::timestamptz, item->>'window_label', item->'window_evidence'
    where not exists (select 1 from public.opportunity_windows where opportunity_version_id = version_id);
    insert into public.review_tasks (opportunity_version_id, task_type, status)
    select version_id, 'publish', 'open'
    where not exists (select 1 from public.review_tasks where opportunity_version_id = version_id and task_type = 'publish' and status in ('open', 'in_review'));
  end loop;
end $$;
